12 |    */
13 |   constructor(viewer, ref) {
14 |     this.viewer = viewer;
15 |     this.ref = ref;
16 | 
17 |     this.containerWidth = 0;
18 |     this.containerHeight = 0;
19 |     this.viewportOrigin = { x: 0, y: 0 };
20 |   }
