45 |   clear() {
46 |     if (!this.context2d) return;
47 | 
48 |     this.context2d.clearRect(0, 0, this.containerWidth, this.containerHeight);
49 |   }
50 | 
51 |   /**
52 |    * resize - resizes the added Canvas overlay.
53 |    */
54 |   resize() {
55 |     if (this.containerWidth !== this.viewer.container.clientWidth) {
56 |       this.containerWidth = this.viewer.container.clientWidth;
57 |       this.canvasDiv.setAttribute('width', this.containerWidth);
58 |       this.canvas.setAttribute('width', this.containerWidth);
59 |     }
60 | 
61 |     if (this.containerHeight !== this.viewer.container.clientHeight) {
62 |       this.containerHeight = this.viewer.container.clientHeight;
63 |       this.canvasDiv.setAttribute('height', this.containerHeight);
64 |       this.canvas.setAttribute('height', this.containerHeight);
65 |     }
66 | 
67 |     const boundsRect = this.viewer.viewport.getBoundsNoRotateWithMargins(true);
68 |     this.viewportOrigin.x = boundsRect.x || 0;
69 |     this.viewportOrigin.y = boundsRect.y || 0;
70 | 
71 |     this.viewportWidth = boundsRect.width;
72 |     this.viewportHeight = boundsRect.height;
73 |   }
74 | 
75 |   /**
76 |    * canvasUpdate - sets up the dimensions for the canvas update to mimick IIIF canvas
77 |    * 0 dimensions. Then call provided update function.
78 |    * @param {Function} update
79 |    */
80 |   canvasUpdate(update) {
81 |     if (!this.context2d) return;
82 | 
83 |     if (this.clearBeforeRedraw) this.clear();
84 |     const { scale } = this;
85 | 
86 |     this.context2d.translate(-this.viewportOrigin.x * scale, -this.viewportOrigin.y * scale);
87 |     this.context2d.scale(scale, scale);
88 | 
89 |     const center = this.viewer.viewport.getCenter();
90 | 
91 |     const flip = this.viewer.viewport.getFlip();
92 |     if (flip) {
93 |       this.context2d.translate(center.x * 2, 0);
94 |       this.context2d.scale(-1, 1);
95 |     }
96 | 
97 |     const rotation = this.viewer.viewport.getRotation();
98 |     if (rotation !== 0) {
99 |       this.context2d.translate(center.x, center.y);
100 |       this.context2d.rotate((rotation * Math.PI) / 180);
101 |       this.context2d.translate(-1 * center.x, -1 * center.y);
102 |     }
103 |     update();
104 | 
