1 | /** */
2 | export default class TruncatedHit {
3 |   /** */
4 |   constructor(hit, annotation = undefined, { maxChars = 200, minimum = 20 } = {}) {
5 |     this.hit = hit;
6 |     this.annotation = annotation;
7 |     this.maxChars = maxChars || 200;
8 |     this.minimum = minimum || 20;
9 |   }
10 | 
11 |   /** */
12 |   get match() {
13 |     return this.hit.match || (this.annotation && this.annotation.resource.resource.chars) || '-';
14 |   }
15 | 
16 |   /** */
17 |   get charsOnSide() {
18 |     const resultingChars = (this.maxChars - this.match.length) / 2;
19 |     const measured = [(this.hit.before || '').length, (this.hit.after || '').length].filter((length) => length > 0);
20 |     return Math.max(Math.min(resultingChars, ...measured), this.minimum);
21 |   }
22 | 
23 |   /** */
24 |   get before() {
25 |     if (!this.hit.before) return '';
26 |     return this.hit.before.substring(this.hit.before.length - this.charsOnSide, this.hit.before.length);
27 |   }
28 | 
29 |   /** */
30 |   get after() {
31 |     if (!this.hit.after) return '';
32 |     return this.hit.after.substring(0, Math.min(this.hit.after.length, this.charsOnSide));
33 |   }
34 | }
